    '#hz-pop .hz-msg{padding:6px 2px;font-size:13px}' +
    '#hz-pop .hz-tip{margin-top:6px;font-size:11px;opacity:.6}' +
    '#hz-toggle{position:fixed;right:12px;bottom:calc(12px + env(safe-area-inset-bottom,0px));z-index:9990;width:38px;height:38px;border-radius:50%;' +
    'display:flex;align-items:center;justify-content:center;font:700 17px "Noto Serif SC",serif;cursor:pointer;' +
    '-webkit-user-select:none;user-select:none;background:rgba(255,255,255,.92);color:#23462C;' +
    'border:1.5px solid rgba(95,160,46,.6);box-shadow:0 4px 12px rgba(20,60,50,.25);opacity:.9}' +
    '#hz-toggle.hz-off{color:#8a948c;border-color:rgba(120,130,125,.5);background:rgba(240,240,240,.9)}' +
