  }

  var padTop = 8, padBot = 8;
  try {
    var pr = document.createElement('div');
    pr.style.cssText = 'position:fixed;left:0;top:0;visibility:hidden;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)';
