      var s = i, two = t.substr(i, 2);
      if (two === 'zh' || two === 'ch' || two === 'sh') i += 2;
      else if ('bpmfdtnlgkhjqxrzcsyw'.indexOf(c) >= 0) i += 1;
      var vs = i;
      while (i < n && isV(t.charAt(i))) i++;
      if (i === vs) {
        if (i === s) i++;
        if (t.slice(s, i) === 'r' && out.length && out[out.length - 1].e === s) out.push({ s: s, e: i, t: out[out.length - 1].t });
        continue;
      }
      var vstr = ''; for (var k = vs; k < i; k++) vstr += plain(t.charAt(k));
      var nx = t.charAt(i);
      if (nx === 'n') {
        if (t.charAt(i + 1) === 'g') { if (isV(t.charAt(i + 2))) i += 1; else i += 2; }
        else if (!isV(t.charAt(i + 1))) i += 1;
      } else if (nx === 'r' && vstr === 'e' && s === vs && !isV(t.charAt(i + 1))) { i += 1; }
      var tone = 5;
      for (var q = s; q < i; q++) { var tc = toneOfChar(t.charAt(q)); if (tc) { tone = tc; break; } }
      if (/[1-5]/.test(t.charAt(i))) { tone = +t.charAt(i); i++; }
      if (i - s === 1 && /[A-Z]/.test(str.charAt(s)) && !isLetter(t.charAt(s - 1)) && !isLetter(t.charAt(i))) continue;
      out.push({ s: s, e: i, t: tone });
    }
    return out;
  }
  function zhuyinSyllables(str) {
    var INIT = 'ㄅㄆㄇㄈㄉㄊㄋㄌㄍㄎㄏㄐㄑㄒㄓㄔㄕㄖㄗㄘㄙ', MED = 'ㄧㄨㄩ', FIN = 'ㄚㄛㄜㄝㄞㄟㄠㄡㄢㄣㄤㄥㄦ';
    var TM = { 'ˊ': 2, 'ˇ': 3, 'ˋ': 4 };
    var out = [], cur = null, n = str.length;
    function isZ(c) { return c !== '' && (INIT.indexOf(c) >= 0 || MED.indexOf(c) >= 0 || FIN.indexOf(c) >= 0); }
    function close(e) {
      if (!cur) return;
      cur.e = e;
      if (cur.t === 0) cur.t = (str.slice(cur.s, e) === 'ㄦ' && out.length) ? out[out.length - 1].t : 1;
      out.push({ s: cur.s, e: cur.e, t: cur.t }); cur = null;
    }
    for (var i = 0; i < n; i++) {
