      if (!role) { close(i); continue; }
      if (cur && ((role === 'I' && (cur.I || cur.M || cur.F)) || (role === 'M' && (cur.M || cur.F)) || (role === 'F' && cur.F))) close(i);
      if (!cur) cur = { s: i, t: 0, I: 0, M: 0, F: 0 };
      cur[role] = 1;
