    close(n);
    return out;
  }
  function hanTones(hanText, pyText, syl) {
    var han = [];
    for (var i = 0; i < hanText.length; i++) if (HANRE.test(hanText.charAt(i))) han.push(i);
    if (!han.length || !syl.length) return [];
    var res = [];
    if (han.length === syl.length) {
      for (var a = 0; a < han.length; a++) res.push({ s: han[a], e: han[a] + 1, t: syl[a].t });
      return res;
    }
    function cid(items, text, isBreakChar) {
      var ids = [], id = 0, prevEnd = -1;
      for (var k = 0; k < items.length; k++) {
        if (k > 0) {
          var between = text.slice(prevEnd, items[k].s), br = false;
          for (var j = 0; j < between.length; j++) if (isBreakChar(between.charAt(j))) { br = true; break; }
