    var hid = cid(hItems, hanText, function (c) { return !/\s/.test(c); });
    var sid = cid(syl, pyText, function (c) { return !/[\s'’\-]/.test(c); });
    if (hid[hid.length - 1] !== sid[sid.length - 1]) return [];
    var hg = {}, sg = {};
    hid.forEach(function (g, k) { (hg[g] = hg[g] || []).push(k); });
    sid.forEach(function (g, k) { (sg[g] = sg[g] || []).push(k); });
    for (var g in hg) {
      if (sg[g] && sg[g].length === hg[g].length)
        for (var m = 0; m < hg[g].length; m++) res.push({ s: han[hg[g][m]], e: han[hg[g][m]] + 1, t: syl[sg[g][m]].t });
    }
    return res;
  }

  function readOn(key, def) {
    try { var v = window.localStorage.getItem(key); return v === null ? def : v === '1'; }
    catch (e) { return def; }
  }
  function saveOn(key, v) { try { window.localStorage.setItem(key, v ? '1' : '0'); } catch (e) {} }

  ['hz-tone-style', 'hz-tone-m', 'hz-tone-e'].forEach(function (id) {
    var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
  });
  var st = document.createElement('style'); st.id = 'hz-tone-style';
  st.textContent =
    '.hz-tp{--t1:#FF7A8C;--t2:#FFAA33;--t3:#6BF08F;--t4:#BFA3FF;--t5:#EEF3F7}' +
    '.hz-tg{--t1:#C5283D;--t2:#B35A00;--t3:#1E7B3A;--t4:#6A35C8;--t5:#5F6E69}' +
    '.nightMode .hz-tg,.night_mode .hz-tg{--t1:#FF8FA3;--t2:#FFB454;--t3:#6FE08F;--t4:#B59CFF;--t5:#A9C2A8}' +
    '.hz-on .hz-t1{color:var(--t1)}.hz-on .hz-t2{color:var(--t2)}.hz-on .hz-t3{color:var(--t3)}' +
    '.hz-on .hz-t4{color:var(--t4)}.hz-on .hz-t5{color:var(--t5)}' +
    '.hz-tp.hz-on .hz-t1,.hz-tp.hz-on .hz-t2,.hz-tp.hz-on .hz-t3,.hz-tp.hz-on .hz-t4,.hz-tp.hz-on .hz-t5{text-shadow:0 0 2px rgba(6,38,74,.95),0 0 5px rgba(6,38,74,.75),0 1px 9px rgba(6,38,74,.55)}' +
    '.hz-tone-btn{position:fixed;bottom:calc(12px + env(safe-area-inset-bottom,0px));z-index:9990;width:38px;height:38px;border-radius:50%;' +
    'display:flex;align-items:center;justify-content:center;font:700 17px "Noto Serif SC",serif;cursor:pointer;' +
    '-webkit-user-select:none;user-select:none;background:rgba(255,255,255,.92);color:#23462C;' +
    'border:1.5px solid rgba(95,160,46,.6);box-shadow:0 4px 12px rgba(20,60,50,.25);opacity:.9}' +
    '.hz-tone-btn.hz-off{color:#8a948c;border-color:rgba(120,130,125,.5);background:rgba(240,240,240,.9)}' +
    '.hz-tone-btn.hz-off:after{content:"";position:absolute;width:26px;height:2px;background:#c0392b;transform:rotate(-45deg)}' +
    '.hz-tone-btn.hz-night{background:rgba(24,36,31,.95);color:#E4F1DA;border-color:rgba(255,255,255,.3)}' +
    '.hz-tone-btn.hz-night.hz-off{color:#7c887f;background:rgba(40,40,40,.95)}';
  document.head.appendChild(st);

  function isNight() {
    var b = document.body, h = document.documentElement;
    return b.classList.contains('nightMode') || b.classList.contains('night_mode') ||
           h.classList.contains('night_mode') || h.classList.contains('nightMode');
