      b.className = 'hz-tone-btn ' + (g.on ? '' : 'hz-off ') + (isNight() ? 'hz-night' : '');
      b.title = 'Màu thanh điệu · ' + g.name + ': ' + (g.on ? 'ĐANG BẬT (bấm để tắt)' : 'ĐANG TẮT (bấm để bật)');
    }
