    document.body.appendChild(b); sync();
  });

  window.__hzToneDispose = function () {
    ['hz-tone-style', 'hz-tone-m', 'hz-tone-e'].forEach(function (id) {
      var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
    });
  };
})();
</script>

