<script>
(function () {
  if (window.__hzAudioDispose) { try { window.__hzAudioDispose(); } catch (e) {} }
  var lastT = 0;
  function boxOf(n) {
    while (n && n !== document) {
      if (n.classList && (n.classList.contains('audio-btn') || n.classList.contains('listen-btn'))) return n;
      n = n.parentNode;
    }
    return null;
  }
  function onTap(e) {
    var box = boxOf(e.target);
    if (!box) return;
    var a = box.querySelector('a.replay-button, a.soundLink, .replay-button');
    if (!a) return;
    box.classList.add('hz-press');
    setTimeout(function () { box.classList.remove('hz-press'); }, 120);
    if (a === e.target || (a.contains && a.contains(e.target))) return;   /* chạm trúng icon: để Anki tự phát */
    var now = Date.now();
    if (now - lastT < 250) return;                                         /* chống phát đúp */
    lastT = now;
    e.preventDefault();
    try { a.click(); } catch (err) {}
  }
  document.addEventListener('click', onTap, true);
  window.__hzAudioDispose = function () { document.removeEventListener('click', onTap, true); };
})();
</script>
