<!-- ============================================================
  笔顺 POPUP · Bôi đen chữ Hán -> hiện thứ tự nét + LUYỆN VIẾT
  Thư viện Hanzi Writer + dữ liệu nét nạp từ jsDelivr (cần Internet).
  ============================================================ -->
<script>
(function () {
  var legacy = !!window.__hzLegacy || (!!window.__hzPopInit && !window.__hzPopDispose);
  if (legacy) window.__hzLegacy = true;
  if (window.__hzPopDispose) { try { window.__hzPopDispose(); } catch (e) {} }
  window.__hzPopInit = true;
  ['hz-pop', 'hz-toggle', 'hz-style'].forEach(function (id) {
    var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
  });
  var VERSION = 'v3';

  var LIB  = 'https://cdn.jsdelivr.net/npm/hanzi-writer@3.7.3/dist/hanzi-writer.min.js';
  var DATA = 'https://cdn.jsdelivr.net/npm/hanzi-writer-data@2.0.1/';
  var MAX  = 12;
  var DEFAULT_ON  = true;
  var SHOW_BUTTON = true;
  var KEY = 'hzStrokePopupOn';
  var HAN  = /[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]/g;

  var pop, body, btn, token = 0, lastKey = '', libState = 0, waiters = [], selTimer;
  var cache = {};

  function readOn() {
    try { var v = window.localStorage.getItem(KEY); return v === null ? DEFAULT_ON : v === '1'; }
    catch (e) { return DEFAULT_ON; }
  }
  function saveOn(v) { try { window.localStorage.setItem(KEY, v ? '1' : '0'); } catch (e) {} }
  var enabled = readOn();

  var st = document.createElement('style'); st.id = 'hz-style';
  st.textContent =
    '#hz-pop{position:fixed;z-index:10000;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;display:none;box-sizing:border-box;max-width:min(94vw,440px);' +
    'padding:10px 12px 8px;border-radius:16px;font:14px/1.4 "Noto Serif",serif;text-align:left;' +
    'background:rgba(255,255,255,.96);color:#23462C;border:1px solid rgba(95,160,46,.35);' +
    'box-shadow:0 12px 34px rgba(20,60,50,.28);-webkit-user-select:none;user-select:none}' +
    '#hz-pop.hz-night{background:rgba(24,36,31,.97);color:#E4F1DA;border-color:rgba(255,255,255,.18)}' +
    '#hz-pop .hz-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;' +
    'font-size:12px;letter-spacing:2px;text-transform:uppercase;opacity:.85}' +
    '#hz-pop .hz-x{border:0;background:rgba(95,160,46,.16);color:inherit;font-size:26px;line-height:1;width:40px;height:40px;border-radius:50%;padding:0;margin:-6px -6px -6px 0;cursor:pointer;flex-shrink:0}' +
    '#hz-pop .hz-body{display:flex;flex-wrap:wrap;gap:8px}' +
    '#hz-pop .hz-tile{width:92px;text-align:center}' +
    '#hz-pop .hz-box{width:92px;height:92px;border-radius:10px;border:1px solid rgba(95,160,46,.45);' +
    'touch-action:none;-ms-touch-action:none;position:relative;' +
    'background-image:linear-gradient(to right,transparent 49.3%,rgba(95,160,46,.28) 50%,transparent 50.7%),' +
    'linear-gradient(to bottom,transparent 49.3%,rgba(95,160,46,.28) 50%,transparent 50.7%)}' +
    '#hz-pop .hz-box.hz-q{border:2px solid #D9677F;cursor:crosshair}' +
    '#hz-pop.hz-night .hz-box{border-color:rgba(255,255,255,.25)}' +
    '#hz-pop .hz-box svg{display:block;touch-action:none}' +
    '#hz-pop .hz-meta{margin-top:3px;min-height:16px;font-size:12px;opacity:.9}' +
    '#hz-pop .hz-bar{display:flex;gap:4px;margin-top:3px}' +
    '#hz-pop .hz-b{flex:1;padding:3px 0;font-size:11px;line-height:1.3;border-radius:8px;cursor:pointer;' +
    'border:1px solid rgba(95,160,46,.5);background:rgba(95,160,46,.1);color:inherit;white-space:nowrap}' +
    '#hz-pop .hz-b.hz-small{flex:0 0 28px}' +
    '#hz-pop .hz-b.on{background:rgba(95,160,46,.35);font-weight:700}' +
    '#hz-pop.hz-night .hz-b{border-color:rgba(255,255,255,.28);background:rgba(255,255,255,.08)}' +
    '#hz-pop.hz-night .hz-b.on{background:rgba(140,198,63,.28)}' +
    '#hz-pop .hz-msg{padding:6px 2px;font-size:13px}' +
    '#hz-pop .hz-tip{margin-top:6px;font-size:11px;opacity:.6}' +
    '#hz-toggle{position:fixed;right:12px;bottom:calc(12px + env(safe-area-inset-bottom,0px));z-index:9990;width:38px;height:38px;border-radius:50%;' +
    'display:flex;align-items:center;justify-content:center;font:700 17px "Noto Serif SC",serif;cursor:pointer;' +
    '-webkit-user-select:none;user-select:none;background:rgba(255,255,255,.92);color:#23462C;' +
    'border:1.5px solid rgba(95,160,46,.6);box-shadow:0 4px 12px rgba(20,60,50,.25);opacity:.9}' +
    '#hz-toggle.hz-off{color:#8a948c;border-color:rgba(120,130,125,.5);background:rgba(240,240,240,.9)}' +
    '#hz-toggle.hz-off:after{content:"";position:absolute;width:26px;height:2px;background:#c0392b;transform:rotate(-45deg)}' +
    '#hz-toggle.hz-night{background:rgba(24,36,31,.95);color:#E4F1DA;border-color:rgba(255,255,255,.3)}' +
    '#hz-toggle.hz-night.hz-off{color:#7c887f;background:rgba(40,40,40,.95)}';
  document.head.appendChild(st);

  function isNight() {
    var b = document.body, h = document.documentElement;
    return b.classList.contains('nightMode') || b.classList.contains('night_mode') ||
           h.classList.contains('night_mode') || h.classList.contains('nightMode');
  }

  function loadLib(cb) {
    if (window.HanziWriter) { cb(true); return; }
    waiters.push(cb);
    if (libState === 1) return;
    libState = 1;
    var s = document.createElement('script');
    s.src = LIB;
    s.onload  = function () { libState = 2; flush(!!window.HanziWriter); };
    s.onerror = function () { libState = 0; flush(false); };
    document.head.appendChild(s);
  }
  function flush(ok) { var w = waiters; waiters = []; for (var i = 0; i < w.length; i++) w[i](ok); }

  function ensurePop() {
    if (pop && document.body.contains(pop)) return;
    pop = document.createElement('div');
    pop.id = 'hz-pop'; pop.setAttribute('data-v', VERSION);
    pop.innerHTML = '<div class="hz-head"><span>笔顺 · Thứ tự nét</span><button class="hz-x" aria-label="Đóng">×</button></div>' +
                    '<div class="hz-body"></div>' +
                    '<div class="hz-tip">Chạm ô chữ: xem lại nét · Luyện viết: vẽ từng nét · chạm ra ngoài hoặc × để đóng · ' + VERSION + '</div>';
    body = pop.querySelector('.hz-body');
    var xb = pop.querySelector('.hz-x');
    xb.addEventListener('click', function (e) { e.preventDefault(); hide(); });
    xb.addEventListener('touchend', function (e) { e.preventDefault(); e.stopPropagation(); hide(); });
    pop.addEventListener('mousedown', function (e) {
      var t = e.target;
      if (!(t && t.closest && t.closest('.hz-box'))) e.preventDefault();
    });
    document.body.appendChild(pop);
  }
  function syncBtn() {
    if (!btn) return;
    btn.className = (enabled ? '' : 'hz-off ') + (isNight() ? 'hz-night' : '');
    btn.title = enabled ? 'Popup nét chữ: ĐANG BẬT (bấm để tắt)' : 'Popup nét chữ: ĐANG TẮT (bấm để bật)';
  }
  function ensureBtn() {
    if (!SHOW_BUTTON || (btn && document.body.contains(btn))) return;
    btn = document.createElement('div');
    btn.id = 'hz-toggle'; btn.setAttribute('data-v', VERSION);
    btn.textContent = '笔';
    btn.addEventListener('click', function () {
      enabled = !enabled; saveOn(enabled);
      if (!enabled) hide();
      syncBtn();
    });
    document.body.appendChild(btn);
    syncBtn();
  }
  ensureBtn();

  var obs;
  try {
    obs = new MutationObserver(function () {
      ['hz-pop', 'hz-toggle'].forEach(function (id) {
        var all = document.querySelectorAll('#' + id);
        for (var i = 0; i < all.length; i++)
          if (!all[i].getAttribute('data-v') && all[i].parentNode) all[i].parentNode.removeChild(all[i]);
      });
    });
    obs.observe(document.body, { childList: true });
  } catch (e) {}

  var closedAt = 0;
  function hide() {
    token++; lastKey = ''; closedAt = Date.now();
    if (pop) pop.style.display = 'none';
    try { var sl = window.getSelection(); if (sl && sl.removeAllRanges) sl.removeAllRanges(); } catch (e) {}
  }

  var padTop = 8, padBot = 8;
  try {
    var pr = document.createElement('div');
    pr.style.cssText = 'position:fixed;left:0;top:0;visibility:hidden;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)';
    document.body.appendChild(pr);
    var cs = window.getComputedStyle(pr);
    var sT = parseFloat(cs.paddingTop) || 0, sB = parseFloat(cs.paddingBottom) || 0;
    document.body.removeChild(pr);
    var touchDev = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
    padTop = 8 + sT + (touchDev ? 40 : 0);
    padBot = 8 + sB + (touchDev ? 24 : 0);
  } catch (e) {}

  function place(rect) {
    var vw = window.innerWidth, vh = window.innerHeight;
    pop.style.maxHeight = Math.max(160, vh - padTop - padBot) + 'px';
    var w = pop.offsetWidth, h = pop.offsetHeight;
    var left = rect.left + rect.width / 2 - w / 2;
    left = Math.max(8, Math.min(left, vw - w - 8));
    var top = rect.bottom + 10;
    if (top + h > vh - padBot) top = rect.top - h - 10;
    if (top < padTop) top = Math.max(padTop, vh - h - padBot);
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';
  }

  function loader(char, ok, err) {
    if (cache[char]) { setTimeout(function () { ok(cache[char]); }, 0); return; }
    var x = new XMLHttpRequest();
    x.open('GET', DATA + encodeURIComponent(char) + '.json', true);
    x.onload = function () {
      if (x.status >= 200 && x.status < 300) {
        try { cache[char] = JSON.parse(x.responseText); ok(cache[char]); } catch (e) { err(e); }
      } else err(x.status);
    };
    x.onerror = function () { err('network'); };
    x.send();
  }

  function show(chars, rect) {
    ensurePop();
    var my = ++token;
    var night = isNight();
    pop.className = night ? 'hz-night' : '';
    body.innerHTML = '';
    pop.style.display = 'block';
    pop.style.visibility = 'hidden';
    place(rect);
    pop.style.visibility = 'visible';

    loadLib(function (ok) {
      if (my !== token) return;
      if (!ok) {
        body.innerHTML = '<div class="hz-msg">Cần kết nối Internet để tải dữ liệu nét chữ.</div>';
        place(rect); return;
      }
      var C = night
        ? { stroke: '#E4F1DA', outline: '#3d5247', radical: '#F29AB0' }
        : { stroke: '#23462C', outline: '#D3E3CC', radical: '#D9677F' };

      chars.forEach(function (ch) {
        var tile = document.createElement('div'); tile.className = 'hz-tile';
        var box  = document.createElement('div'); box.className = 'hz-box';
        var meta = document.createElement('div'); meta.className = 'hz-meta'; meta.textContent = '…';
        var bar  = document.createElement('div'); bar.className = 'hz-bar';
        var bQuiz = document.createElement('div'); bQuiz.className = 'hz-b'; bQuiz.textContent = '✍ Luyện viết';
        bar.appendChild(bQuiz);
        tile.appendChild(box); tile.appendChild(meta); tile.appendChild(bar); body.appendChild(tile);

        var loop = 0, writer = null, mode = 'anim', total = 0, mistakes = 0, nextStroke = 0, ovTimer = null;

        function mk(extra) {
          box.innerHTML = '';
          var o = {
            width: 90, height: 90, padding: 6,
            showCharacter: false, showOutline: true,
            strokeColor: C.stroke, radicalColor: C.radical, outlineColor: C.outline,
            strokeAnimationSpeed: 1.3, delayBetweenStrokes: 120,
            drawingColor: C.stroke, drawingWidth: 5,
            charDataLoader: loader,
            onLoadCharDataError: function () { meta.textContent = 'không có dữ liệu'; }
          };
          for (var k in extra) o[k] = extra[k];
          writer = window.HanziWriter.create(box, ch, o);
        }

        function play() {
          var id = ++loop;
          (function step() {
            if (my !== token || id !== loop || mode !== 'anim' || !writer) return;
            writer.animateCharacter({ onComplete: function () {
              setTimeout(function () { if (my === token && id === loop) step(); }, 1100);
            }});
          })();
        }

        function animate() {
          loop++; mode = 'anim';
          bQuiz.className = 'hz-b'; bQuiz.textContent = '✍ Luyện viết'; box.classList.remove('hz-q');
          mk({ onLoadCharDataSuccess: function (d) {
            total = d.strokes.length;
            meta.textContent = total + ' nét';
            if (my === token) { place(rect); play(); }
          }});
        }

        function practice() {
          loop++; mode = 'quiz'; mistakes = 0;
          bQuiz.className = 'hz-b on'; bQuiz.textContent = '↻ Làm lại'; box.classList.add('hz-q'); nextStroke = 0;
          mk({ onLoadCharDataSuccess: function (d) {
            if (my !== token || mode !== 'quiz') return;
            total = d.strokes.length;
            meta.textContent = 'Vẽ nét 1/' + total;
            try { writer.quiz({
              leniency: 1, showHintAfterMisses: 3, highlightOnComplete: true,
              onMistake: function (s) {
                mistakes++;
                meta.textContent = 'Nét ' + (s.strokeNum + 1) + '/' + total + ' · sai ' + mistakes;
              },
              onCorrectStroke: function (s) {
                nextStroke = s.strokeNum + 1;
                meta.textContent = 'Nét ' + Math.min(s.strokeNum + 2, total) + '/' + total + ' · sai ' + mistakes;
              },
              onComplete: function (s) {
                var m = (s && typeof s.totalMistakes === 'number') ? s.totalMistakes : mistakes;
                meta.textContent = m === 0 ? '✓ Hoàn hảo!' : '✓ Xong · sai ' + m + ' nét';
              }
            }); } catch (err) { meta.textContent = 'Lỗi: ' + (err && err.message ? err.message : err); }
            place(rect);
          }});
        }

        bQuiz.addEventListener('click', practice);
        box.addEventListener('click', function () { if (mode === 'anim' && writer) play(); });

        animate();
      });
      place(rect);
    });
  }

  function handleSel() {
    if (!enabled) return;
    ensureBtn();
    if (Date.now() - closedAt < 700) return;
    var sel = window.getSelection();
    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
    if (pop && sel.anchorNode && pop.contains(sel.anchorNode)) return;
    var m = sel.toString().match(HAN);
    if (!m) return;
    var seen = {}, chars = [];
    for (var i = 0; i < m.length && chars.length < MAX; i++) {
      if (!seen[m[i]]) { seen[m[i]] = 1; chars.push(m[i]); }
    }
    var key = chars.join('');
    if (key === lastKey && pop && pop.style.display === 'block') return;
    lastKey = key;
    show(chars, sel.getRangeAt(0).getBoundingClientRect());
  }

  var L = [];
  function on(type, fn, opt) {
    var h = function (e) {
      fn(e);
      if (legacy && !(pop && e.target && pop.contains && pop.contains(e.target))) e.stopPropagation();
    };
    window.addEventListener(type, h, opt || true);
    L.push([type, h, opt || true]);
  }
  on('mouseup',  function () { setTimeout(handleSel, 10); });
  on('touchend', function () { setTimeout(handleSel, 30); });
  on('selectionchange', function () {
    clearTimeout(selTimer); selTimer = setTimeout(handleSel, 350);
  });
  function outside(e) { if (pop && pop.style.display === 'block' && !pop.contains(e.target)) hide(); }
  on('mousedown',  outside);
  on('touchstart', outside, { passive: true, capture: true });
  on('keydown', function (e) { if (e.key === 'Escape') hide(); });

  window.__hzPopDispose = function () {
    clearTimeout(selTimer); token++; try { if (obs) obs.disconnect(); } catch (e) {}
    L.forEach(function (x) { window.removeEventListener(x[0], x[1], x[2]); });
    ['hz-pop', 'hz-toggle', 'hz-style'].forEach(function (id) {
      var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
    });
  };
})();
</script>

<!-- ============================================================
  拼 · Ẩn pinyin / zhuyin / pinyin câu ví dụ cho tới khi chạm
  Nút 拼 ở góc dưới phải: BẬT = hiện, TẮT (gạch chéo) = che mờ; chạm phần bị che để xem tạm.
  ============================================================ -->
<script>
(function () {
  if (window.__hzPinDispose) { try { window.__hzPinDispose(); } catch (e) {} }
  var DEFAULT_SHOW = false;
  var HIDE_TRANSLATION = false;
  var SHOW_BUTTON = true;
  var KEY = 'hzPinyinShowOn';
  var SEL = '.pinyin-txt,.zhuyin-txt,.ex-pinyin' + (HIDE_TRANSLATION ? ',.ex-trans' : '');

  function read() {
    try { var v = window.localStorage.getItem(KEY); return v === null ? !DEFAULT_SHOW : v !== '1'; }
    catch (e) { return !DEFAULT_SHOW; }
  }
  function save(hideNow) { try { window.localStorage.setItem(KEY, hideNow ? '0' : '1'); } catch (e) {} }
  var hide = read();

  ['hz-pin-style', 'hz-pin-toggle'].forEach(function (id) {
    var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
  });
  var st = document.createElement('style'); st.id = 'hz-pin-style';
  st.textContent =
    '.pinyin-txt.hz-veil,.zhuyin-txt.hz-veil{display:inline-block}' +
    '.hz-veil.hz-hide{filter:blur(7px);cursor:pointer;-webkit-user-select:none;user-select:none;transition:filter .2s}' +
    '.hz-veil.hz-hide.hz-show{filter:none}' +
    '#hz-pin-toggle{position:fixed;right:58px;bottom:calc(12px + env(safe-area-inset-bottom,0px));z-index:9990;width:38px;height:38px;border-radius:50%;' +
    'display:flex;align-items:center;justify-content:center;font:700 17px "Noto Serif SC",serif;cursor:pointer;' +
    '-webkit-user-select:none;user-select:none;background:rgba(255,255,255,.92);color:#23462C;' +
    'border:1.5px solid rgba(95,160,46,.6);box-shadow:0 4px 12px rgba(20,60,50,.25);opacity:.9}' +
    '#hz-pin-toggle.hz-off{color:#8a948c;border-color:rgba(120,130,125,.5);background:rgba(240,240,240,.9)}' +
    '#hz-pin-toggle.hz-off:after{content:"";position:absolute;width:26px;height:2px;background:#c0392b;transform:rotate(-45deg)}' +
    '#hz-pin-toggle.hz-night{background:rgba(24,36,31,.95);color:#E4F1DA;border-color:rgba(255,255,255,.3)}' +
    '#hz-pin-toggle.hz-night.hz-off{color:#7c887f;background:rgba(40,40,40,.95)}';
  document.head.appendChild(st);

  function isNight() {
    var b = document.body, h = document.documentElement;
    return b.classList.contains('nightMode') || b.classList.contains('night_mode') ||
           h.classList.contains('night_mode') || h.classList.contains('nightMode');
  }

  var els = document.querySelectorAll(SEL);
  function apply() {
    for (var i = 0; i < els.length; i++) {
      els[i].classList.add('hz-veil');
      if (hide) els[i].classList.add('hz-hide'); else els[i].classList.remove('hz-hide');
      els[i].classList.remove('hz-show');
    }
  }
  for (var i = 0; i < els.length; i++) {
    (function (el) {
      el.addEventListener('click', function () { if (hide) el.classList.toggle('hz-show'); });
    })(els[i]);
  }
  apply();

  var btn;
  function sync() {
    if (!btn) return;
    btn.className = (hide ? 'hz-off ' : '') + (isNight() ? 'hz-night' : '');
    btn.title = hide ? 'Pinyin: ĐANG ẨN (bấm để hiện)' : 'Pinyin: ĐANG HIỆN (bấm để ẩn)';
  }
  if (SHOW_BUTTON) {
    btn = document.createElement('div');
    btn.id = 'hz-pin-toggle';
    btn.textContent = '拼';
    btn.addEventListener('click', function () { hide = !hide; save(hide); apply(); sync(); });
    document.body.appendChild(btn);
    sync();
  }

  window.__hzPinDispose = function () {
    ['hz-pin-style', 'hz-pin-toggle'].forEach(function (id) {
      var n = document.getElementById(id); if (n && n.parentNode) n.parentNode.removeChild(n);
    });
  };
})();
</script>

<!-- ============================================================
  声 · TÔ MÀU THEO THANH ĐIỆU (thanh 1, 2, 3, 4, thanh nhẹ) — ngoại tuyến
  2 nút góc dưới phải: 声 = nhóm TỪ · 例 = nhóm CÂU VÍ DỤ
  ============================================================ -->
<script>
(function () {
  if (window.__hzToneDispose) { try { window.__hzToneDispose(); } catch (e) {} }
  var DEFAULT_MAIN = true;
  var DEFAULT_EX   = true;
  var SHOW_BUTTON  = true;
  var KEY_MAIN = 'hzToneMainOn', KEY_EX = 'hzToneExOn';

  var T1 = 'āēīōūǖ', T2 = 'áéíóúǘ', T3 = 'ǎěǐǒǔǚ', T4 = 'àèìòùǜ';
  var VOW = 'aeiouüvê' + T1 + T2 + T3 + T4;
  var HANRE = /[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]/;
  function isV(c) { return c !== '' && VOW.indexOf(c) >= 0; }
  function isLetter(c) { return c !== '' && (/[a-z]/.test(c) || isV(c)); }
  function toneOfChar(c) {
    if (T1.indexOf(c) >= 0) return 1; if (T2.indexOf(c) >= 0) return 2;
    if (T3.indexOf(c) >= 0) return 3; if (T4.indexOf(c) >= 0) return 4; return 0;
  }
  function plain(c) {
    var m = { 'ā':'a','á':'a','ǎ':'a','à':'a','ē':'e','é':'e','ě':'e','è':'e','ī':'i','í':'i','ǐ':'i','ì':'i',
              'ō':'o','ó':'o','ǒ':'o','ò':'o','ū':'u','ú':'u','ǔ':'u','ù':'u','ǖ':'ü','ǘ':'ü','ǚ':'ü','ǜ':'ü' };
    return m[c] || c;
